    bg = grid[0][0]
    marker = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]

    def bridge_line(coords):
        # coords is ordered (index, row, column) for original marker cells.
        if not coords:
            return
        # Group contiguous marker cells into runs.
        runs = []
        for pos, r, c in coords:
            if not runs or pos > runs[-1][-1][0] + 1:
                runs.append([])
            runs[-1].append((pos, r, c))
        # Broken long strokes are recognized as three or more separate pieces.
        # With just two pieces, only a small interruption is bridged.
        for left, right in zip(runs, runs[1:]):
            a, b = left[-1][0], right[0][0]
            gap = b - a - 1
            if gap <= 0 or (len(runs) < 3 and gap > 2):
                continue
            for pos in range(a + 1, b):
                if coords[0][1] == coords[-1][1]:
                    r, c = coords[0][1], pos
                else:
                    r, c = pos, coords[0][2]
                if grid[r][c] == bg:
                    out[r][c] = 2

    for r in range(h):
        bridge_line([(c, r, c) for c in range(w) if grid[r][c] == marker])
    for c in range(w):
        bridge_line([(r, r, c) for r in range(h) if grid[r][c] == marker])
    return out

